import{_ as o,l as n,o as e,c as l,v as t,p as s,x as r,d,i as h,S as E}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"Gibbard–Satterthwaite","description":"","frontmatter":{"title":"Gibbard–Satterthwaite","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/gibbard-satterthwaite.md","filePath":"econ/gibbard-satterthwaite.md","lastUpdated":1789023840000}'),p={name:"econ/gibbard-satterthwaite.md"};function A(c,a,b,m,f,B){const i=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="gibbard–satterthwaite" tabindex="-1">Gibbard–Satterthwaite <a class="header-anchor" href="#gibbard–satterthwaite" aria-label="Permalink to &quot;Gibbard–Satterthwaite&quot;">​</a></h1><div class="epigraph"><p>若备选方案不少于三个、偏好定义域不受限，则非独裁的社会选择无法在占优策略下实施。</p><footer>—— Gibbard, Manipulation of Voting Schemes, Econometrica, 1973；Satterthwaite, Strategy-proofness and Arrow’s Conditions, JET, 1975</footer></div><p><a href="/econ/myerson-virtual-value">上一课</a>在拟线性货币里把最优拍卖写成虚拟价值铁钟；再往前，VCG 还能占优策略实施有效配置。缺口是把货币拿掉：只对方案排序投票。此时占优策略 IC 几乎只留下独裁。本课钉这条不可能，作为信息课序在「没有转移」一端的收束，不重写拍卖公式，也不把单峰定义域的中位投票写成解。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>有限方案集 \\(A\\)，\\(|A|\\ge 3\\)。每人报一个严格排序，社会选择函数 \\(f\\) 吐出一个方案。策略证明：报真排序是占优策略。到上（onto）或帕累托：每个方案都可能被选，或一致同意的方案必被选。Gibbard–Satterthwaite：满足这些的 \\(f\\) 必是独裁——存在 \\(i\\)，使 \\(f\\) 永远等于 \\(i\\) 的最爱。</p><p>与 Arrow 的对照：Arrow 在社会排序上要帕累托、无关方案独立性、非独裁，结论是不可能。GS 在社会选择（只吐一个点）上要策略证明，结论同样是独裁。两条定理可互推（在适当技术条件下）：策略证明大约相当于 IIA 加帕累托。显示原理在这里已经用过：只需看直接报排序的规则。</p><h3 id="不可能的是占优策略-不是贝叶斯" tabindex="-1">不可能的是占优策略，不是贝叶斯 <a class="header-anchor" href="#不可能的是占优策略-不是贝叶斯" aria-label="Permalink to &quot;不可能的是占优策略，不是贝叶斯&quot;">​</a></h3><p>允许先验、只要求贝叶斯 IC，能实施的更多，但依赖共同先验，投票场合往往没有。Myerson 拍卖走贝叶斯层，并且有货币把偏好收成数字；GS 两者都没有。</p><p><span class="marginnote">独裁不是「有人说了算就效率低」。独裁策略证明、也帕累托（对独裁者）。定理说的是：要想非独裁，就必须放弃占优策略或限制定义域。VCG 逃出去，是因为拟线性加转移把定义域收成另一类偏好。</span></p><p>\\(|A|=2\\) 时多数规则策略证明，定理从三个方案起算。 无差异、随机化（随机独裁、随机中位）可以放松，本课只钉确定性 SCF。 操纵就是谎报排序使 \\(f\\) 对自己更好；定理说非独裁规则总有人能这样。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对象：有限 \\(A\\)，普遍定义域（所有严格排序都可报），确定性 \\(f\\)。结论：策略证明 + 到上 \\(\\Rightarrow\\) 独裁。证明策略不在此重写；课堂上认两点：VCG 用的货币不在工具箱里；<a href="/econ/matching-strategy-proof">DA</a> 能单边策略证明，是因为匹配的结果空间与定义域都不是「任意 \\(A\\) 上的任意排序」。</p>',12)),(e(),s(E,null,{default:r(()=>[h(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20MON%5B%22%E6%8B%9F%E7%BA%BF%E6%80%A7%20%2B%20%E8%B4%A7%E5%B8%81%EF%BC%9AVCG%20%2F%20Myerson%22%5D%20--%3E%20DROP%5B%22%E6%8B%BF%E6%8E%89%E8%BD%AC%E7%A7%BB%22%5D%0A%20%20UNIV%5B%22%7CA%7C%E2%89%A53%EF%BC%8C%E6%99%AE%E9%81%8D%E5%AE%9A%E4%B9%89%E5%9F%9F%22%5D%20--%3E%20GS%5B%22%E7%AD%96%E7%95%A5%E8%AF%81%E6%98%8E%20%E2%87%92%20%E7%8B%AC%E8%A3%81%22%5D%0A%20%20DOM%5B%22%E9%99%90%E5%88%B6%E5%AE%9A%E4%B9%89%E5%9F%9F%EF%BC%9A%E5%8D%95%E5%B3%B0%22%5D%20--%3E%20MED%5B%22%E4%B8%AD%E4%BD%8D%E6%8A%95%E7%A5%A8%E5%8F%AF%E7%AD%96%E7%95%A5%E8%AF%81%E6%98%8E%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>没有转移时，无法用「付你造成的外部性」对齐私人目标与社会目标。占优策略要求：无论别人报什么，单个人不能靠谎报把结果扳向自己更爱的方案。三个以上方案提供足够空间让非独裁规则在某对偏好轮廓上被扳动——这是操纵的几何。独裁把空间缩成一个人的最爱，谎报无益。</p><p>匹配 DA 不违反 GS：方案集是匹配，偏好被限制成「只关心自己的对象」，不是 \\(A\\) 上的任意排序；而且 DA 只对一边策略证明。拍卖 VCG 不违反 GS：偏好是拟线性的，结果含货币。GS 钉的是无限制序数偏好、无货币、确定性选择。三个方案已经够造出「循环」：非独裁规则必须在某对轮廓上让某人的第二选择压过第一，于是他有谎报动机。这是操纵的最小几何，与 Arrow 的 IIA 失败同源。</p><p>\\(|A|=2\\) 时多数规则策略证明，定理从三个方案起算。 随机独裁、单峰中位是后继放松，不是对本定理的否定。 显示原理已经用过：只需看直接报排序的规则，弯程序救不了。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>单峰偏好（Black、Moulin）：中位投票策略证明，定义域限制救了实施。可分物品、拟线性，VCG 再救一次。随机社会选择、近似策略证明、大规模匿名，都是后继放松。不要把 GS 写成「投票无用」：它说占优策略 + 普遍定义域太强；制度靠的是定义域、议程、货币或重复博弈。</p><p>后课进入<a href="/econ/potential-outcomes">潜在结果</a>，不再把因果系数当成某个策略证明的社会选择。信息课序在此收束：有货币则包络与虚值，无货币则 GS。宏观核算更后才出现。</p><h3 id="显示原理没有取消不可能" tabindex="-1">显示原理没有取消不可能 <a class="header-anchor" href="#显示原理没有取消不可能" aria-label="Permalink to &quot;显示原理没有取消不可能&quot;">​</a></h3><p>任何间接投票规则的占优策略均衡结果，都能收成直接策略证明的 \\(f\\)。因此「设计更弯的投票程序」救不了：若直接的 \\(f\\) 只能是独裁，间接的也只能实施独裁结果。这与 Myerson–Satterthwaite、竞争筛选无均衡同一逻辑——可行 IC 集太小。</p><p><span class="marginnote">Gibbard 1973 用博弈形式；Satterthwaite 1975 连到 Arrow。课堂上记：三个方案、普遍定义域、占优策略、非随机 ⇒ 独裁。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无转移、普遍定义域、\\(|A|\\ge 3\\)：策略证明的 SCF 必独裁。</li><li>VCG / Myerson 靠拟线性货币逃出；DA 靠受限偏好与单边。</li><li>显示原理表明弯程序救不了。</li><li>要非独裁，必须限定义域、加随机、加货币或放弃占优策略。</li><li>出处：Gibbard, <em>Econometrica</em> 1973；Satterthwaite, <em>JET</em> 1975。</li></ul>',12))])}const u=o(p,[["render",A]]);export{_ as __pageData,u as default};
